package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse;import in.kabadiwala.connect.model.MaterialCategory;import in.kabadiwala.connect.repository.MaterialCategoryRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/materials") public class MaterialController {private final MaterialCategoryRepository r;public MaterialController(MaterialCategoryRepository r){this.r=r;}@GetMapping ApiResponse<?> active(){return ApiResponse.ok("Materials",r.findByActiveTrue());}@PostMapping @PreAuthorize("hasRole('ADMIN')") ApiResponse<?> create(@RequestBody MaterialCategory c){if(c.code==null||c.code.isBlank())throw new IllegalArgumentException("Category code required");return ApiResponse.ok("Category created",r.save(c));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")ApiResponse<?> update(@PathVariable String id,@RequestBody MaterialCategory c){var x=r.findById(id).orElseThrow();x.names=c.names;x.iconUrl=c.iconUrl;x.units=c.units;x.active=c.active;return ApiResponse.ok("Category updated",r.save(x));}@PatchMapping("/{id}/active")@PreAuthorize("hasRole('ADMIN')")ApiResponse<?> active(@PathVariable String id,@RequestParam boolean active){var x=r.findById(id).orElseThrow();x.active=active;return ApiResponse.ok("Category updated",r.save(x));}}
